function Confirmation({ reservation, onBack }) {
  const isPending = reservation.status === 'pending_approval';

  return (
    <div className="confirmation">
      <div className="confirmation-card">
        <div className="success-icon">{isPending ? '⏳' : '✅'}</div>
        <h2 className={isPending ? 'pending-title' : ''}>
          {isPending
            ? 'Talebiniz Alındı!'
            : 'Rezervasyon Tamamlandı!'}
        </h2>
        {isPending && (
          <p className="pending-desc">
            Ödemeniz Escrow hesabına alındı. Araç sahibinin onayını bekliyorsunuz.
          </p>
        )}
        <div className="reservation-details">
          <h3>🚗 {reservation.vehicle.brand} {reservation.vehicle.model}</h3>
          <p>📋 Rezervasyon No: <strong>#{reservation.id}</strong></p>
          <p>🔑 İşlem ID: <strong>{reservation.transactionId}</strong></p>
          <p>📅 Başlangıç: <strong>{reservation.startDate}</strong></p>
          <p>📅 Bitiş: <strong>{reservation.endDate}</strong></p>
          <p>💰 Tutar: <strong>₺{reservation.amount}</strong></p>
          <div className={`status-badge ${isPending ? 'pending' : 'confirmed'}`}>
            {isPending ? '⏳ ONAY BEKLİYOR' : '✓ CONFIRMED'}
          </div>
        </div>
        <button onClick={onBack}>Ana Sayfaya Dön</button>
      </div>
    </div>
  );
}

export default Confirmation;
